def is_regular(s):
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def longest_regular_substrings(s):
    n = len(s)
    max_length = 0
    count = 0
    dp = [0] * (n + 1)

    for i in range(1, n + 1):
        if s[i - 1] == ')':
            if i > 1 and s[i - 2] == '(':
                dp[i] = dp[i - 2] + 2
            elif i > dp[i - 1] and s[i - dp[i - 1] - 1] == '(':
                dp[i] = dp[i - 1] + 2 + dp[i - dp[i - 1] - 2]

            if dp[i] > max_length:
                max_length = dp[i]
                count = 1
            elif dp[i] == max_length:
                count += 1

    return max_length, count

